            Assert.That(store.TrySave(g, "P2 isolated radius", out var error), Is.True, error);
        }
        [UnityTest] public IEnumerator SavedRadiusReachesGpuOnlyAtBoundariesAndRestoresAcrossResetAndSceneReentry()
