            Assert.That(m.Buffers.unitTypeSettingsBuffer, Is.SameAs(unchangedBuffer)); Assert.That(d.CancelEditing(), Is.True);
            Check(m, baseline, .6f, count, "rejected-grid-density-keeps-gpu");
